<?php require dirname(__DIR__,2).'/app/bootstrap.php';Auth::requireLogin();$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT * FROM transcripts WHERE id=? AND user_id=? AND status='completed'");$s->execute([$id,Auth::id()]);$t=$s->fetch();if(!$t){http_response_code(404);exit('Transcript not found');}$s=db()->prepare('SELECT start_seconds,end_seconds,content FROM transcript_segments WHERE transcript_id=? ORDER BY sequence_no');$s->execute([$id]);$segs=$s->fetchAll();$f=$_GET['format']??'txt';$name='transcript-'.$id;if($f==='json'){header('Content-Type: application/json');header('Content-Disposition: attachment; filename="'.$name.'.json"');echo json_encode(['title'=>$t['title'],'language'=>$t['language'],'text'=>$t['transcript_text'],'segments'=>$segs],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE);exit;}if($f==='txt'){header('Content-Type: text/plain; charset=utf-8');header('Content-Disposition: attachment; filename="'.$name.'.txt"');echo $t['transcript_text'];exit;}if(in_array($f,['srt','vtt'],true)){if(!$segs){http_response_code(422);exit('This transcription provider did not return timestamped segments.');}header('Content-Type: text/plain; charset=utf-8');header('Content-Disposition: attachment; filename="'.$name.'.'.$f.'"');if($f==='vtt')echo "WEBVTT\n\n";foreach($segs as $i=>$v){$fmt=fn($n)=>sprintf('%02d:%02d:%02d'.($f==='vtt'?'.':',').'%03d',floor($n/3600),floor(($n%3600)/60),floor($n%60),round(($n-floor($n))*1000));if($f==='srt')echo ($i+1)."\n";echo $fmt($v['start_seconds']).' --> '.$fmt($v['end_seconds'])."\n".$v['content']."\n\n";}exit;}http_response_code(400);exit('Unsupported format');
